const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').split('\n');
const [N, M] = data[0].trim().split(/\s+/).map(Number);
const grid = [];
for (let i = 0; i < N; i++) {
    grid.push(data[i + 1].trimEnd());
}

let sr = 0, sc = 0;
for (let j = 0; j < M; j++) {
    if (grid[0][j] === 'o') {
        sc = j;
        break;
    }
}

const queueR = new Int32Array(N * M);
const queueC = new Int32Array(N * M);
let head = 0, tail = 0;
queueR[tail] = sr;
queueC[tail] = sc;
tail++;

while (head < tail) {
    const r = queueR[head];
    const c = queueC[head];
    head++;

    if (r + 1 < N) {
        const below = grid[r + 1][c];
        if (below === '.') {
            grid[r + 1][c] = 'o';
            queueR[tail] = r + 1;
            queueC[tail] = c;
            tail++;
        } else if (below === '#') {
            if (c - 1 >= 0 && grid[r][c - 1] === '.') {
                grid[r][c - 1] = 'o';
                queueR[tail] = r;
                queueC[tail] = c - 1;
                tail++;
            }
            if (c + 1 < M && grid[r][c + 1] === '.') {
                grid[r][c + 1] = 'o';
                queueR[tail] = r;
                queueC[tail] = c + 1;
                tail++;
            }
        }
    }
}

console.log(grid.join('\n'));
